CREATE TABLE repositories(id uuid PRIMARY KEY,name varchar(200) NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true);
CREATE TABLE source_files(id uuid PRIMARY KEY,name varchar(200) NOT NULL UNIQUE,provider varchar(8) NOT NULL,audience varchar(20) NOT NULL,active_version uuid,deleted boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE documents(id uuid PRIMARY KEY,source_id uuid NOT NULL REFERENCES source_files(id),content_hash varchar(64) NOT NULL,model varchar(100) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE document_chunks(id uuid PRIMARY KEY,document_id uuid NOT NULL REFERENCES documents(id) ON DELETE CASCADE,heading varchar(500) NOT NULL,start_line integer NOT NULL,end_line integer NOT NULL,content text NOT NULL,content_tsv tsvector GENERATED ALWAYS AS(to_tsvector('simple',content)) STORED);
CREATE INDEX chunks_fts ON document_chunks USING gin(content_tsv);
CREATE TABLE embeddings(id uuid PRIMARY KEY REFERENCES document_chunks(id) ON DELETE CASCADE,embedding public.vector(1536) NOT NULL,model varchar(100) NOT NULL);
CREATE INDEX embeddings_hnsw ON embeddings USING hnsw(embedding public.vector_cosine_ops);
CREATE TABLE code_relations(id uuid PRIMARY KEY,from_document_id uuid REFERENCES documents(id),to_symbol varchar(300) NOT NULL,relation_type varchar(30) NOT NULL);
CREATE TABLE chat_sessions(id uuid PRIMARY KEY,owner varchar(40) NOT NULL,provider varchar(8) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE chat_messages(id uuid PRIMARY KEY,session_id uuid NOT NULL REFERENCES chat_sessions(id) ON DELETE CASCADE,role varchar(20) NOT NULL,content_masked text NOT NULL,status varchar(20) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id uuid PRIMARY KEY,actor varchar(40) NOT NULL,event_type varchar(50) NOT NULL,target_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE retrieval_logs(id uuid PRIMARY KEY,actor varchar(40) NOT NULL,chunk_ids jsonb NOT NULL,latency_ms bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tool_invocations(id uuid PRIMARY KEY,actor varchar(40) NOT NULL,tool_name varchar(60) NOT NULL,outcome varchar(20) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ingestion_jobs(id uuid PRIMARY KEY,source_name varchar(200) NOT NULL,status varchar(20) NOT NULL,detail varchar(300) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE feedback(id uuid PRIMARY KEY,message_id uuid NOT NULL REFERENCES chat_messages(id) ON DELETE CASCADE,owner varchar(40) NOT NULL,rating integer NOT NULL CHECK(rating IN(-1,1)),UNIQUE(message_id,owner));
CREATE TABLE prompt_templates(name varchar(100) NOT NULL,version integer NOT NULL,template text NOT NULL,PRIMARY KEY(name,version));
CREATE TABLE agent_runs(id uuid PRIMARY KEY,session_id uuid REFERENCES chat_sessions(id),status varchar(20) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events(id uuid PRIMARY KEY,event_type varchar(50) NOT NULL,status varchar(20) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE processed_events(event_id uuid PRIMARY KEY,processed_at timestamptz NOT NULL DEFAULT now());
GRANT USAGE ON SCHEMA knowledge TO sis_knowledge;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA knowledge TO sis_knowledge;
REVOKE UPDATE,DELETE ON knowledge.audit_logs FROM sis_knowledge;
REVOKE ALL ON knowledge.flyway_schema_history FROM sis_knowledge;
